UPDATE dashboard_widget SET name = #{name}, data_source = #{dataSource}, refresh_rate_seconds = #{refreshRateSeconds},
       config = #{config}, status = #{status}, category = #{category}, description = #{description}, updated_at = #{updatedAt}
WHERE widget_id = #{widgetId} AND tenant_id = #{tenantId}

mapper.select:
SELECT widget_id, tenant_id, type, name, data_source, refresh_rate_seconds, config, status, category, description, created_at, updated_at
FROM dashboard_widget
WHERE tenant_id = #{tenantId}
AND category = #{category}
ORDER BY category, name

