UPDATE dashboard_calendar_event SET title = #{title}, description = #{description}, event_type = #{eventType},
    start_time = #{startTime}, end_time = #{endTime}, business_type = #{businessType}, business_id = #{businessId},
    color = #{color}, all_day = #{allDay}, reminder = #{reminder}, updated_at = #{updatedAt}
WHERE event_id = #{eventId} AND tenant_id = #{tenantId}

mapper.select:
SELECT event_id, tenant_id, user_id, title, description, event_type, start_time, end_time,
       business_type, business_id, color, all_day, reminder, created_at, updated_at
FROM dashboard_calendar_event WHERE tenant_id = #{tenantId} AND event_id = #{eventId}

SELECT event_id, tenant_id, user_id, title, description, event_type, start_time, end_time,
       business_type, business_id, color, all_day, reminder, created_at, updated_at
FROM dashboard_calendar_event
WHERE tenant_id = #{tenantId} AND user_id = #{userId}
AND start_time >= #{startTime}
AND end_time <= #{endTime}
ORDER BY start_time ASC

